fn integration_activation_risk_for_query(
    query: &IntegrationActivationRiskQuery,
) -> (Vec<IntegrationActivationRiskItem>, usize) {
    let catalog = first_party_catalog();
    let catalog_count = catalog.len();
    let (candidates, _) = integration_activation_candidates_for_query(&query.candidates);
    let mut risks = activation_risk_from_candidates(&catalog, candidates.iter());

    if let Some(kind) = query.risk_kind {
        risks.retain(|risk| risk.kind == kind);
    }
    if let Some(required_tier) = query.required_tier {
        risks.retain(|risk| risk.required_tier == required_tier);
    }
    if let Some(policy_surface) = query.policy_surface {
        risks.retain(|risk| risk.policy_surface == Some(policy_surface));
    }
    if let Some(requires_attention) = query.requires_attention {
        risks.retain(|risk| risk.requires_attention() == requires_attention);
    }
    if let Some(limit) = query.risk_limit {
        risks.truncate(limit);
    }

    (risks, catalog_count)
}

fn integration_activation_actions_for_query(
    query: &IntegrationActivationActionQuery,
) -> (Vec<IntegrationActivationAction>, usize) {
    let (candidates, catalog_count) =
        integration_activation_candidates_for_query(&query.candidates);
    let mut actions = activation_actions_from_candidates(candidates.iter());

    if let Some(action_kind) = query.action_kind {
        actions.retain(|action| action.kind == action_kind);
    }
    if let Some(limit) = query.action_limit {
        actions.truncate(limit);
    }

    (actions, catalog_count)
}

fn integration_activation_agenda_for_query(
    query: &IntegrationActivationAgendaQuery,
) -> (Vec<IntegrationActivationAgendaStage>, usize) {
    let (candidates, catalog_count) =
        integration_activation_candidates_for_query(&query.candidates);
    let mut agenda = activation_agenda_from_candidates(candidates);

    if query.candidates_per_stage_limit.is_some() || query.actions_per_stage_limit.is_some() {
        for stage in &mut agenda {
            if let Some(limit) = query.candidates_per_stage_limit {
                stage.candidates.truncate(limit);
                stage.candidate_summary =
                    IntegrationActivationCandidateSummary::from_candidates(stage.candidates.iter());
                stage.actions = activation_actions_from_candidates(stage.candidates.iter());
            }
            if let Some(limit) = query.actions_per_stage_limit {
                stage.actions.truncate(limit);
            }
            stage.action_summary =
                IntegrationActivationActionSummary::from_actions(stage.actions.iter());
        }
    }
    if let Some(limit) = query.stage_limit {
        agenda.truncate(limit);
    }

    (agenda, catalog_count)
}

fn limited_slice<T>(items: &[T], limit: Option<usize>) -> &[T] {
    match limit {
        Some(limit) => &items[..items.len().min(limit)],
        None => items,
    }
}

fn list_integrations_output_handler_output(query: IntegrationCatalogQuery) -> ToolHandlerOutput {
    let catalog = first_party_catalog();
    let entries = query_integrations(&catalog, &query);
    let count = entries.len();
    ToolHandlerOutput::new(list_integrations_output_json(&catalog, entries)).with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("list_integrations")),
            ("count", integer(count as i64)),
        ]),
    )
}

fn describe_integration_output_handler_output(
    arguments: &JsonValue,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let _ = expect_object(arguments)?;
    let integration_id = IntegrationId::trusted(required_string(arguments, "integration_id")?);
    let catalog = first_party_catalog();
    let entry = find_entry(&catalog, &integration_id).ok_or_else(|| {
        validation_error(format!(
            "unknown integration_id `{}`",
            integration_id.as_str()
        ))
    })?;
    let available_primitives = optional_primitive_list(arguments, "available_primitives")?;
    let allowed_capabilities = optional_capability_id_list(arguments, "allowed_capability_ids")?;
    let enabled_integrations = optional_integration_id_list(arguments, "enabled_integrations")?;
    let plan = activation_plan_for_entry(entry);
    let report = readiness_report_for_plan(
        &plan,
        &available_primitives,
        &allowed_capabilities,
        &enabled_integrations,
    );

    Ok(
        ToolHandlerOutput::new(describe_integration_output_json(entry, &plan, &report)).with_event(
            ToolEventKind::Progress,
            object([
                ("operation", string("describe_integration")),
                ("integration_id", string(integration_id.as_str())),
                (
                    "activation_ready",
                    JsonValue::Bool(report.activation_ready()),
                ),
            ]),
        ),
    )
}

fn list_primitives_output_handler_output(
    arguments: &JsonValue,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let _ = expect_object(arguments)?;
    let priority = optional_u8(arguments, "priority_at_or_before")?.unwrap_or(u8::MAX);
    let include_ecosystem_coverage =
        optional_bool(arguments, "include_ecosystem_coverage")?.unwrap_or(true);
    let limit = optional_u64(arguments, "limit")?.map(|value| value as usize);
    let output = list_primitives_output_json(
        priority,
        include_ecosystem_coverage,
        limit.unwrap_or(usize::MAX),
    );
    let backlog_count = json_field(&output, "backlog_count")
        .and_then(json_integer)
        .unwrap_or(0);

    Ok(ToolHandlerOutput::new(output).with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("list_primitives")),
            ("backlog_count", integer(backlog_count)),
        ]),
    ))
}

fn describe_primitive_output_handler_output(
    arguments: &JsonValue,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let _ = expect_object(arguments)?;
    let primitive = parse_primitive_family(&required_string(arguments, "primitive")?)?;
    let priority = optional_u8(arguments, "priority_at_or_before")?.unwrap_or(u8::MAX);
    let output = describe_primitive_output_json(primitive, priority);
    let integration_count = json_field(&output, "integration_count")
        .and_then(json_integer)
        .unwrap_or(0);

    Ok(ToolHandlerOutput::new(output).with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("describe_primitive")),
            ("primitive", string(primitive.as_str())),
            ("integration_count", integer(integration_count)),
        ]),
    ))
}

