fn command_risk_audit_rows(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: &CommandRiskAuditQuery,
) -> Result<(Vec<CommandRiskAuditRow>, CommandRiskAuditSummary), ToolCallError> {
    let mut command_query = RuntimeCommandResultQuery::new()
        .sorted_by(RuntimeCommandResultSort::StatusThenSequenceDesc);
    if let Some(bridge_id) = query.bridge_id.clone() {
        command_query = command_query.for_bridge(bridge_id);
    }
    let command_statuses = command_risk_statuses_for_query(query);
    for status in command_statuses {
        command_query = command_query.with_status(status);
    }

    let command_output = runtime
        .execute_read_tool(
            principal_id.clone(),
            RuntimeReadToolRequest::ListCommandResults {
                query: command_query,
            },
            now_ms,
        )
        .map_err(runtime_error)?;
    let RuntimeReadToolOutput::CommandResults { results, .. } = command_output else {
        return Err(ToolCallError {
            kind: ToolErrorKind::ToolExecutionError,
            message: "command risk audit expected command result output".to_string(),
            details: JsonValue::Null,
        });
    };

    let mut authorization_query = RuntimeAuthorizationDecisionQuery::new();
    if let Some(principal_id) = query.principal_id.clone() {
        authorization_query = authorization_query.for_principal(principal_id);
    }
    if let Some(outcome) = command_risk_authorization_outcome_for_query(query) {
        authorization_query = authorization_query.with_outcome(outcome);
    }
    authorization_query =
        authorization_query.sorted_by(RuntimeAuthorizationDecisionSort::DecidedAtDesc);

    let authorization_output = runtime
        .execute_read_tool(
            principal_id,
            RuntimeReadToolRequest::ListAuthorizationDecisions {
                query: authorization_query,
            },
            now_ms,
        )
        .map_err(runtime_error)?;
    let RuntimeReadToolOutput::AuthorizationDecisions { decisions, .. } = authorization_output
    else {
        return Err(ToolCallError {
            kind: ToolErrorKind::ToolExecutionError,
            message: "command risk audit expected authorization decision output".to_string(),
            details: JsonValue::Null,
        });
    };

    let mut rows = results
        .iter()
        .map(CommandRiskAuditRow::from_command_result)
        .chain(
            decisions
                .iter()
                .filter_map(CommandRiskAuditRow::from_authorization_decision),
        )
        .filter(|row| command_risk_audit_row_matches(row, query))
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .blocked
            .cmp(&left.blocked)
            .then_with(|| right.requires_attention.cmp(&left.requires_attention))
            .then_with(|| command_risk_sort_key(right).cmp(&command_risk_sort_key(left)))
            .then_with(|| left.audit_id.cmp(&right.audit_id))
    });
    let summary = CommandRiskAuditSummary::from_rows(&rows);
    Ok((rows, summary))
}

fn command_risk_audit_row_matches(
    row: &CommandRiskAuditRow,
    query: &CommandRiskAuditQuery,
) -> bool {
    if query.risk_only && !row.requires_attention {
        return false;
    }
    if query.failures_only && !row.is_failure_result() {
        return false;
    }
    if query.denials_only && !row.is_denial() {
        return false;
    }
    if query.approval_gated_only && !row.is_approval_gated() {
        return false;
    }
    true
}

fn command_risk_statuses_for_query(query: &CommandRiskAuditQuery) -> Vec<CommandStatus> {
    if !query.command_statuses.is_empty() {
        return query.command_statuses.clone();
    }
    if query.failures_only {
        return vec![
            CommandStatus::Rejected,
            CommandStatus::TimedOut,
            CommandStatus::Failed,
        ];
    }
    Vec::new()
}

fn command_risk_authorization_outcome_for_query(
    query: &CommandRiskAuditQuery,
) -> Option<AuthorizationOutcome> {
    query.authorization_outcome.or(if query.denials_only {
        Some(AuthorizationOutcome::Denied)
    } else {
        None
    })
}

fn command_risk_sort_key(row: &CommandRiskAuditRow) -> u64 {
    row.sequence.or(row.decided_at_ms).unwrap_or(0)
}

fn command_risk_is_approval_gated(tier: PrivilegeTier) -> bool {
    matches!(tier, PrivilegeTier::HumanApproval | PrivilegeTier::HighRisk)
}

const AUTHORIZATION_GAP_EXPIRING_SOON_MS: u64 = 7 * 24 * 60 * 60 * 1_000;

#[derive(Debug, Clone, PartialEq)]
struct AuthorizationGapAuditRow {
    audit_id: String,
    source: &'static str,
    principal_id: AgentId,
    subject: Option<AuthorizationSubject>,
    grant_id: Option<CapabilityGrantId>,
    grant_scope: Option<CapabilityGrantScope>,
    grant_status: Option<CapabilityGrantStatus>,
    outcome: Option<AuthorizationOutcome>,
    required_tier: Option<PrivilegeTier>,
    max_tier: Option<PrivilegeTier>,
    required_capabilities: Vec<CapabilityId>,
    matched_grants: Vec<CapabilityGrantId>,
    missing_capabilities: Vec<CapabilityId>,
    decided_at_ms: Option<u64>,
    granted_at_ms: Option<u64>,
    expires_at_ms: Option<u64>,
    risk_lane: &'static str,
    risk_action: &'static str,
    blocked: bool,
    requires_attention: bool,
}

impl AuthorizationGapAuditRow {
    fn from_decision(decision: &AuthorizationDecision) -> Self {
        let missing_capability_count = decision.missing_capabilities.len();
        let approval_gated = command_risk_is_approval_gated(decision.required_tier);
        let blocked = !decision.is_allowed() || missing_capability_count > 0;
        let requires_attention = blocked || approval_gated;
        let (risk_lane, risk_action) = if blocked {
            ("authorization_gap", "grant_missing_capabilities")
        } else if approval_gated {
            ("approval_gate", "review_authorization_gate")
        } else {
            ("authorization", "monitor_authorization")
        };

        Self {
            audit_id: format!(
                "authorization:{}:{}",
                decision.decided_at_ms,
                authorization_subject_audit_key(&decision.subject)
            ),
            source: "authorization_decision",
            principal_id: decision.principal_id.clone(),
            subject: Some(decision.subject.clone()),
            grant_id: None,
            grant_scope: None,
            grant_status: None,
            outcome: Some(decision.outcome),
            required_tier: Some(decision.required_tier),
            max_tier: None,
            required_capabilities: decision.required_capabilities.clone(),
            matched_grants: decision.matched_grants.clone(),
            missing_capabilities: decision.missing_capabilities.clone(),
            decided_at_ms: Some(decision.decided_at_ms),
            granted_at_ms: None,
            expires_at_ms: None,
            risk_lane,
            risk_action,
            blocked,
            requires_attention,
        }
    }

    fn from_grant(grant: &CapabilityGrant, now_ms: u64) -> Self {
        let status = grant.status_at(now_ms);
        let expiring_soon = grant.expires_at_ms.is_some_and(|expires| {
            expires >= now_ms && expires <= now_ms + AUTHORIZATION_GAP_EXPIRING_SOON_MS
        });
        let (risk_lane, risk_action, blocked, requires_attention) = match status {
            CapabilityGrantStatus::Pending => ("grant_review", "approve_pending_grant", true, true),
            CapabilityGrantStatus::Revoked => ("grant_review", "replace_revoked_grant", true, true),
            CapabilityGrantStatus::Expired => ("grant_review", "renew_expired_grant", true, true),
            CapabilityGrantStatus::Active if expiring_soon => {
                ("grant_expiry", "renew_expiring_grant", false, true)
            }
            CapabilityGrantStatus::Active => ("authorization", "monitor_grant", false, false),
        };

        Self {
            audit_id: format!("capability_grant:{}", grant.grant_id.as_str()),
            source: "capability_grant",
            principal_id: grant.principal_id.clone(),
            subject: None,
            grant_id: Some(grant.grant_id.clone()),
            grant_scope: Some(grant.scope.clone()),
            grant_status: Some(status),
            outcome: None,
            required_tier: None,
            max_tier: Some(grant.max_tier),
            required_capabilities: Vec::new(),
            matched_grants: Vec::new(),
            missing_capabilities: Vec::new(),
            decided_at_ms: None,
            granted_at_ms: Some(grant.granted_at_ms),
            expires_at_ms: grant.expires_at_ms,
            risk_lane,
            risk_action,
            blocked,
            requires_attention,
        }
    }

    fn is_denial(&self) -> bool {
        self.outcome == Some(AuthorizationOutcome::Denied)
    }

    fn has_missing_capabilities(&self) -> bool {
        !self.missing_capabilities.is_empty()
    }

    fn is_approval_gated(&self) -> bool {
        self.required_tier
            .or(self.max_tier)
            .is_some_and(command_risk_is_approval_gated)
    }

    fn needs_review(&self) -> bool {
        self.requires_attention
            && (self.source == "capability_grant"
                || self.risk_lane == "approval_gate"
                || self.risk_lane == "authorization_gap")
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct AuthorizationGapAuditSummary {
    total_rows: usize,
    authorization_decision_rows: usize,
    capability_grant_rows: usize,
    denied_decision_rows: usize,
    allowed_decision_rows: usize,
    missing_capability_rows: usize,
    total_missing_capabilities: usize,
    approval_gated_rows: usize,
    grant_review_rows: usize,
    pending_grant_rows: usize,
    revoked_grant_rows: usize,
    expired_grant_rows: usize,
    expiring_grant_rows: usize,
    blocked_rows: usize,
    requires_attention_rows: usize,
    unique_principals: usize,
}

impl AuthorizationGapAuditSummary {
    fn from_rows(rows: &[AuthorizationGapAuditRow]) -> Self {
        let mut summary = Self::default();
        let mut principals = BTreeSet::new();
        for row in rows {
            summary.total_rows += 1;
            principals.insert(row.principal_id.as_str().to_string());
            match row.source {
                "authorization_decision" => {
                    summary.authorization_decision_rows += 1;
                    match row.outcome {
                        Some(AuthorizationOutcome::Allowed) => summary.allowed_decision_rows += 1,
                        Some(AuthorizationOutcome::Denied) => summary.denied_decision_rows += 1,
                        None => {}
                    }
                }
                "capability_grant" => {
                    summary.capability_grant_rows += 1;
                    match row.grant_status {
                        Some(CapabilityGrantStatus::Pending) => {
                            summary.pending_grant_rows += 1;
                            summary.grant_review_rows += 1;
                        }
                        Some(CapabilityGrantStatus::Revoked) => {
                            summary.revoked_grant_rows += 1;
                            summary.grant_review_rows += 1;
                        }
                        Some(CapabilityGrantStatus::Expired) => {
                            summary.expired_grant_rows += 1;
                            summary.grant_review_rows += 1;
                        }
                        Some(CapabilityGrantStatus::Active) if row.risk_lane == "grant_expiry" => {
                            summary.expiring_grant_rows += 1;
                            summary.grant_review_rows += 1;
                        }
                        Some(CapabilityGrantStatus::Active) | None => {}
                    }
                }
                _ => {}
            }
            if row.has_missing_capabilities() {
                summary.missing_capability_rows += 1;
                summary.total_missing_capabilities += row.missing_capabilities.len();
            }
            if row.is_approval_gated() {
                summary.approval_gated_rows += 1;
            }
            if row.blocked {
                summary.blocked_rows += 1;
            }
            if row.requires_attention {
                summary.requires_attention_rows += 1;
            }
        }
        summary.unique_principals = principals.len();
        summary
    }

    fn has_authorization_gaps(&self) -> bool {
        self.requires_attention_rows > 0
    }

    fn has_missing_capability_gaps(&self) -> bool {
        self.total_missing_capabilities > 0
    }

    fn has_grant_review_pressure(&self) -> bool {
        self.grant_review_rows > 0
    }

    fn has_blockers(&self) -> bool {
        self.blocked_rows > 0
    }
}

fn list_authorization_gap_audit_output_handler_output(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: AuthorizationGapAuditQuery,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let (mut rows, summary) = authorization_gap_audit_rows(runtime, principal_id, now_ms, &query)?;
    if let Some(limit) = query.limit {
        rows.truncate(limit);
    }

    Ok(ToolHandlerOutput::new(object([
        (
            "authorization_gap_audit",
            JsonValue::Array(rows.iter().map(authorization_gap_audit_row_json).collect()),
        ),
        ("summary", authorization_gap_audit_summary_json(&summary)),
        ("count", integer(rows.len() as i64)),
    ]))
    .with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("list_authorization_gap_audit")),
            ("count", integer(rows.len() as i64)),
            (
                "requires_attention_rows",
                integer(summary.requires_attention_rows as i64),
            ),
            ("blocked_rows", integer(summary.blocked_rows as i64)),
            (
                "missing_capability_rows",
                integer(summary.missing_capability_rows as i64),
            ),
            (
                "grant_review_rows",
                integer(summary.grant_review_rows as i64),
            ),
        ]),
    ))
}

fn get_authorization_gap_audit_summary_output_handler_output(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: AuthorizationGapAuditQuery,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let (_, summary) = authorization_gap_audit_rows(runtime, principal_id, now_ms, &query)?;

    Ok(ToolHandlerOutput::new(object([(
        "summary",
        authorization_gap_audit_summary_json(&summary),
    )]))
    .with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("get_authorization_gap_audit_summary")),
            (
                "requires_attention_rows",
                integer(summary.requires_attention_rows as i64),
            ),
            ("blocked_rows", integer(summary.blocked_rows as i64)),
            (
                "missing_capability_rows",
                integer(summary.missing_capability_rows as i64),
            ),
            (
                "grant_review_rows",
                integer(summary.grant_review_rows as i64),
            ),
        ]),
    ))
}

fn authorization_gap_audit_rows(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: &AuthorizationGapAuditQuery,
) -> Result<(Vec<AuthorizationGapAuditRow>, AuthorizationGapAuditSummary), ToolCallError> {
    let mut authorization_query =
        RuntimeAuthorizationDecisionQuery::new().sorted_by(match query.sort {
            AuthorizationGapAuditSort::DecidedAtAsc => {
                RuntimeAuthorizationDecisionSort::DecidedAtAsc
            }
            _ => RuntimeAuthorizationDecisionSort::DecidedAtDesc,
        });
    if let Some(principal_id) = query.principal_id.clone() {
        authorization_query = authorization_query.for_principal(principal_id);
    }
    if let Some(outcome) = query.outcome.or(if query.denials_only {
        Some(AuthorizationOutcome::Denied)
    } else {
        None
    }) {
        authorization_query = authorization_query.with_outcome(outcome);
    }

    let authorization_output = runtime
        .execute_read_tool(
            principal_id.clone(),
            RuntimeReadToolRequest::ListAuthorizationDecisions {
                query: authorization_query,
            },
            now_ms,
        )
        .map_err(runtime_error)?;
    let RuntimeReadToolOutput::AuthorizationDecisions { decisions, .. } = authorization_output
    else {
        return Err(ToolCallError {
            kind: ToolErrorKind::ToolExecutionError,
            message: "authorization gap audit expected authorization decision output".to_string(),
            details: JsonValue::Null,
        });
    };

    let mut grant_query = RuntimeCapabilityGrantQuery::new().sorted_by(match query.sort {
        AuthorizationGapAuditSort::PrincipalId => RuntimeCapabilityGrantSort::PrincipalId,
        _ if query.review_needed_only => RuntimeCapabilityGrantSort::ExpiresAtAsc,
        _ => RuntimeCapabilityGrantSort::PrincipalId,
    });
    if let Some(principal_id) = query.principal_id.clone() {
        grant_query = grant_query.for_principal(principal_id);
    }
    if let Some(status) = query.grant_status {
        grant_query = grant_query.with_status(status);
    }
    if let Some(scope_kind) = query.scope_kind {
        grant_query = grant_query.with_scope_kind(scope_kind);
    }
    if let Some(capability_id) = query.capability_id.clone() {
        grant_query = grant_query.with_capability(capability_id);
    }
    if let Some(entity_id) = query.entity_id.clone() {
        grant_query = grant_query.for_entity(entity_id);
    }

    let grant_output = runtime
        .execute_read_tool(
            principal_id,
            RuntimeReadToolRequest::ListCapabilityGrants { query: grant_query },
            now_ms,
        )
        .map_err(runtime_error)?;
    let RuntimeReadToolOutput::CapabilityGrants { grants, .. } = grant_output else {
        return Err(ToolCallError {
            kind: ToolErrorKind::ToolExecutionError,
            message: "authorization gap audit expected capability grant output".to_string(),
            details: JsonValue::Null,
        });
    };

    let mut rows = decisions
        .iter()
        .map(AuthorizationGapAuditRow::from_decision)
        .chain(
            grants
                .iter()
                .map(|grant| AuthorizationGapAuditRow::from_grant(grant, now_ms)),
        )
        .filter(|row| authorization_gap_audit_row_matches(row, query))
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| authorization_gap_row_cmp(left, right, query.sort));
    let summary = AuthorizationGapAuditSummary::from_rows(&rows);
    Ok((rows, summary))
}

fn authorization_gap_audit_row_matches(
    row: &AuthorizationGapAuditRow,
    query: &AuthorizationGapAuditQuery,
) -> bool {
    if query.denials_only && !row.is_denial() {
        return false;
    }
    if query.missing_capabilities_only && !row.has_missing_capabilities() {
        return false;
    }
    if query.approval_gated_only && !row.is_approval_gated() {
        return false;
    }
    if query.review_needed_only && !row.needs_review() {
        return false;
    }
    if query.requires_attention_only && !row.requires_attention {
        return false;
    }
    if query
        .outcome
        .is_some_and(|outcome| row.outcome != Some(outcome))
    {
        return false;
    }
    if query
        .grant_status
        .is_some_and(|status| row.grant_status != Some(status))
    {
        return false;
    }
    if query
        .scope_kind
        .is_some_and(|scope_kind| authorization_gap_row_scope_kind(row) != Some(scope_kind))
    {
        return false;
    }
    if query
        .capability_id
        .as_ref()
        .is_some_and(|capability_id| !authorization_gap_row_has_capability(row, capability_id))
    {
        return false;
    }
    if query
        .entity_id
        .as_ref()
        .is_some_and(|entity_id| authorization_gap_row_entity_id(row) != Some(entity_id))
    {
        return false;
    }
    if query
        .risk_lane
        .as_ref()
        .is_some_and(|risk_lane| row.risk_lane != risk_lane.as_str())
    {
        return false;
    }
    if query
        .risk_action
        .as_ref()
        .is_some_and(|risk_action| row.risk_action != risk_action.as_str())
    {
        return false;
    }
    true
}

fn authorization_gap_row_cmp(
    left: &AuthorizationGapAuditRow,
    right: &AuthorizationGapAuditRow,
    sort: AuthorizationGapAuditSort,
) -> std::cmp::Ordering {
    match sort {
        AuthorizationGapAuditSort::DecidedAtAsc => authorization_gap_row_time(left)
            .cmp(&authorization_gap_row_time(right))
            .then_with(|| left.audit_id.cmp(&right.audit_id)),
        AuthorizationGapAuditSort::DecidedAtDesc => authorization_gap_row_time(right)
            .cmp(&authorization_gap_row_time(left))
            .then_with(|| left.audit_id.cmp(&right.audit_id)),
        AuthorizationGapAuditSort::PrincipalId => left
            .principal_id
            .cmp(&right.principal_id)
            .then_with(|| authorization_gap_row_rank(right).cmp(&authorization_gap_row_rank(left)))
            .then_with(|| left.audit_id.cmp(&right.audit_id)),
        AuthorizationGapAuditSort::RiskDesc => authorization_gap_row_rank(right)
            .cmp(&authorization_gap_row_rank(left))
            .then_with(|| authorization_gap_row_time(right).cmp(&authorization_gap_row_time(left)))
            .then_with(|| left.audit_id.cmp(&right.audit_id)),
    }
}

fn authorization_gap_row_rank(row: &AuthorizationGapAuditRow) -> u8 {
    if row.has_missing_capabilities() || row.is_denial() {
        5
    } else if matches!(
        row.grant_status,
        Some(CapabilityGrantStatus::Expired | CapabilityGrantStatus::Revoked)
    ) {
        4
    } else if row.grant_status == Some(CapabilityGrantStatus::Pending) {
        3
    } else if row.risk_lane == "grant_expiry" || row.is_approval_gated() {
        2
    } else if row.requires_attention {
        1
    } else {
        0
    }
}

fn authorization_gap_row_time(row: &AuthorizationGapAuditRow) -> u64 {
    row.decided_at_ms
        .or(row.expires_at_ms)
        .or(row.granted_at_ms)
        .unwrap_or(0)
}

fn authorization_subject_audit_key(subject: &AuthorizationSubject) -> String {
    match subject {
        AuthorizationSubject::Tool(tool) => tool.descriptor().tool_id.to_string(),
        AuthorizationSubject::Command { command_id, .. } => command_id.as_str().to_string(),
    }
}

fn authorization_gap_row_scope_kind(
    row: &AuthorizationGapAuditRow,
) -> Option<RuntimeCapabilityGrantScopeKind> {
    match row.grant_scope.as_ref()? {
        CapabilityGrantScope::Tool(_) => Some(RuntimeCapabilityGrantScopeKind::Tool),
        CapabilityGrantScope::Capability(_) => Some(RuntimeCapabilityGrantScopeKind::Capability),
        CapabilityGrantScope::EntityCapability { .. } => {
            Some(RuntimeCapabilityGrantScopeKind::EntityCapability)
        }
        CapabilityGrantScope::AllSmartHome => Some(RuntimeCapabilityGrantScopeKind::AllSmartHome),
    }
}

fn authorization_gap_row_has_capability(
    row: &AuthorizationGapAuditRow,
    capability_id: &CapabilityId,
) -> bool {
    row.required_capabilities
        .iter()
        .chain(row.missing_capabilities.iter())
        .any(|candidate| candidate == capability_id)
        || row.grant_scope.as_ref().is_some_and(|scope| match scope {
            CapabilityGrantScope::Capability(granted) => granted == capability_id,
            CapabilityGrantScope::EntityCapability {
                capability_id: granted,
                ..
            } => granted == capability_id,
            CapabilityGrantScope::AllSmartHome | CapabilityGrantScope::Tool(_) => false,
        })
}

fn authorization_gap_row_entity_id(row: &AuthorizationGapAuditRow) -> Option<&EntityId> {
    if let Some(AuthorizationSubject::Command { entity_id, .. }) = &row.subject {
        return Some(entity_id);
    }
    match row.grant_scope.as_ref() {
        Some(CapabilityGrantScope::EntityCapability { entity_id, .. }) => Some(entity_id),
        _ => None,
    }
}

#[derive(Debug, Clone, PartialEq)]
enum PlatformAccessReviewRecord {
    CommandRisk(CommandRiskAuditRow),
    AuthorizationGap(AuthorizationGapAuditRow),
}

impl PlatformAccessReviewRecord {
    fn review_kind(&self) -> PlatformAccessReviewKind {
        match self {
            Self::CommandRisk(_) => PlatformAccessReviewKind::CommandRisk,
            Self::AuthorizationGap(_) => PlatformAccessReviewKind::AuthorizationGap,
        }
    }

    fn review_id(&self) -> String {
        format!(
            "{}:{}",
            platform_access_review_kind_label(self.review_kind()),
            self.source_id()
        )
    }

    fn source(&self) -> &'static str {
        match self {
            Self::CommandRisk(row) => row.source,
            Self::AuthorizationGap(row) => row.source,
        }
    }

    fn source_id(&self) -> &str {
        match self {
            Self::CommandRisk(row) => &row.audit_id,
            Self::AuthorizationGap(row) => &row.audit_id,
        }
    }

    fn principal_id(&self) -> Option<&AgentId> {
        match self {
            Self::CommandRisk(row) => row.principal_id.as_ref(),
            Self::AuthorizationGap(row) => Some(&row.principal_id),
        }
    }

    fn bridge_id(&self) -> Option<&BridgeId> {
        match self {
            Self::CommandRisk(row) => row.bridge_id.as_ref(),
            Self::AuthorizationGap(_) => None,
        }
    }

    fn entity_id(&self) -> Option<&EntityId> {
        match self {
            Self::CommandRisk(row) => row.entity_id.as_ref(),
            Self::AuthorizationGap(row) => authorization_gap_row_entity_id(row),
        }
    }

    fn command_id(&self) -> Option<&CommandId> {
        match self {
            Self::CommandRisk(row) => row.command_id.as_ref(),
            Self::AuthorizationGap(row) => match &row.subject {
                Some(AuthorizationSubject::Command { command_id, .. }) => Some(command_id),
                _ => None,
            },
        }
    }

    fn grant_id(&self) -> Option<&CapabilityGrantId> {
        match self {
            Self::CommandRisk(_) => None,
            Self::AuthorizationGap(row) => row.grant_id.as_ref(),
        }
    }

    fn status(&self) -> Option<CommandStatus> {
        match self {
            Self::CommandRisk(row) => row.status,
            Self::AuthorizationGap(_) => None,
        }
    }

    fn outcome(&self) -> Option<AuthorizationOutcome> {
        match self {
            Self::CommandRisk(row) => row.outcome,
            Self::AuthorizationGap(row) => row.outcome,
        }
    }

    fn grant_status(&self) -> Option<CapabilityGrantStatus> {
        match self {
            Self::CommandRisk(_) => None,
            Self::AuthorizationGap(row) => row.grant_status,
        }
    }

    fn risk_lane(&self) -> &'static str {
        match self {
            Self::CommandRisk(row) => row.risk_lane,
            Self::AuthorizationGap(row) => row.risk_lane,
        }
    }

    fn risk_action(&self) -> &'static str {
        match self {
            Self::CommandRisk(row) => row.risk_action,
            Self::AuthorizationGap(row) => row.risk_action,
        }
    }

    fn blocked(&self) -> bool {
        match self {
            Self::CommandRisk(row) => row.blocked,
            Self::AuthorizationGap(row) => row.blocked,
        }
    }

    fn requires_attention(&self) -> bool {
        match self {
            Self::CommandRisk(row) => row.requires_attention,
            Self::AuthorizationGap(row) => row.requires_attention,
        }
    }

    fn is_denial(&self) -> bool {
        self.outcome() == Some(AuthorizationOutcome::Denied)
    }

    fn is_failure_result(&self) -> bool {
        matches!(self, Self::CommandRisk(row) if row.is_failure_result())
    }

    fn missing_capability_count(&self) -> usize {
        match self {
            Self::CommandRisk(row) => row.missing_capability_count,
            Self::AuthorizationGap(row) => row.missing_capabilities.len(),
        }
    }

    fn is_approval_gated(&self) -> bool {
        match self {
            Self::CommandRisk(row) => row.is_approval_gated(),
            Self::AuthorizationGap(row) => row.is_approval_gated(),
        }
    }

    fn is_grant_review(&self) -> bool {
        matches!(
            self,
            Self::AuthorizationGap(row)
                if row.source == "capability_grant" && row.needs_review()
        )
    }

    fn has_capability(&self, capability_id: &CapabilityId) -> bool {
        match self {
            Self::CommandRisk(row) => row
                .missing_capabilities
                .iter()
                .any(|candidate| candidate == capability_id),
            Self::AuthorizationGap(row) => authorization_gap_row_has_capability(row, capability_id),
        }
    }

    fn source_record_json(&self) -> JsonValue {
        match self {
            Self::CommandRisk(row) => command_risk_audit_row_json(row),
            Self::AuthorizationGap(row) => authorization_gap_audit_row_json(row),
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct PlatformAccessReviewSummary {
    total_rows: usize,
    command_risk_rows: usize,
    authorization_gap_rows: usize,
    command_result_rows: usize,
    authorization_decision_rows: usize,
    capability_grant_rows: usize,
    denied_decision_rows: usize,
    command_failure_rows: usize,
    missing_capability_rows: usize,
    total_missing_capabilities: usize,
    approval_gated_rows: usize,
    grant_review_rows: usize,
    blocked_rows: usize,
    requires_attention_rows: usize,
    unique_principals: usize,
    unique_entities: usize,
}

impl PlatformAccessReviewSummary {
    fn from_records(records: &[PlatformAccessReviewRecord]) -> Self {
        let mut summary = Self::default();
        let mut principals = BTreeSet::new();
        let mut entities = BTreeSet::new();
        for record in records {
            summary.total_rows += 1;
            match record.review_kind() {
                PlatformAccessReviewKind::CommandRisk => summary.command_risk_rows += 1,
                PlatformAccessReviewKind::AuthorizationGap => summary.authorization_gap_rows += 1,
            }
            match record.source() {
                "command_result" => summary.command_result_rows += 1,
                "authorization_decision" => summary.authorization_decision_rows += 1,
                "capability_grant" => summary.capability_grant_rows += 1,
                _ => {}
            }
            if let Some(principal_id) = record.principal_id() {
                principals.insert(principal_id.as_str().to_string());
            }
            if let Some(entity_id) = record.entity_id() {
                entities.insert(entity_id.as_str().to_string());
            }
            if record.is_denial() {
                summary.denied_decision_rows += 1;
            }
            if record.is_failure_result() {
                summary.command_failure_rows += 1;
            }
            let missing_capability_count = record.missing_capability_count();
            if missing_capability_count > 0 {
                summary.missing_capability_rows += 1;
                summary.total_missing_capabilities += missing_capability_count;
            }
            if record.is_approval_gated() {
                summary.approval_gated_rows += 1;
            }
            if record.is_grant_review() {
                summary.grant_review_rows += 1;
            }
            if record.blocked() {
                summary.blocked_rows += 1;
            }
            if record.requires_attention() {
                summary.requires_attention_rows += 1;
            }
        }
        summary.unique_principals = principals.len();
        summary.unique_entities = entities.len();
        summary
    }

    fn status(&self) -> &'static str {
        if self.blocked_rows > 0 {
            "blocked"
        } else if self.requires_attention_rows > 0 {
            "review"
        } else {
            "ready"
        }
    }

    fn ready(&self) -> bool {
        self.blocked_rows == 0
    }

    fn has_access_risks(&self) -> bool {
        self.requires_attention_rows > 0
    }

    fn has_blockers(&self) -> bool {
        self.blocked_rows > 0
    }

    fn recommended_action(&self) -> &'static str {
        if self.denied_decision_rows > 0 || self.missing_capability_rows > 0 {
            "grant_missing_capabilities"
        } else if self.command_failure_rows > 0 {
            "inspect_command_failures"
        } else if self.grant_review_rows > 0 {
            "review_capability_grants"
        } else if self.approval_gated_rows > 0 {
            "review_approval_gates"
        } else if self.requires_attention_rows > 0 {
            "review_platform_access_pressure"
        } else {
            "monitor_platform_access"
        }
    }
}

fn list_platform_access_review_output_handler_output(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: PlatformAccessReviewQuery,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let (mut records, summary) =
        platform_access_review_records(runtime, principal_id, now_ms, &query)?;
    if let Some(limit) = query.limit {
        records.truncate(limit);
    }

    Ok(ToolHandlerOutput::new(object([
        (
            "platform_access_review",
            JsonValue::Array(
                records
                    .iter()
                    .map(platform_access_review_record_json)
                    .collect(),
            ),
        ),
        ("summary", platform_access_review_summary_json(&summary)),
        ("count", integer(records.len() as i64)),
    ]))
    .with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("list_platform_access_review")),
            ("count", integer(records.len() as i64)),
            ("status", string(summary.status())),
            ("ready", JsonValue::Bool(summary.ready())),
            (
                "requires_attention_rows",
                integer(summary.requires_attention_rows as i64),
            ),
            ("blocked_rows", integer(summary.blocked_rows as i64)),
            ("next_action", string(summary.recommended_action())),
        ]),
    ))
}

fn get_platform_access_review_summary_output_handler_output(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: PlatformAccessReviewQuery,
) -> Result<ToolHandlerOutput, ToolCallError> {
    let (_, summary) = platform_access_review_records(runtime, principal_id, now_ms, &query)?;

    Ok(ToolHandlerOutput::new(object([(
        "summary",
        platform_access_review_summary_json(&summary),
    )]))
    .with_event(
        ToolEventKind::Progress,
        object([
            ("operation", string("get_platform_access_review_summary")),
            ("status", string(summary.status())),
            ("ready", JsonValue::Bool(summary.ready())),
            (
                "requires_attention_rows",
                integer(summary.requires_attention_rows as i64),
            ),
            ("blocked_rows", integer(summary.blocked_rows as i64)),
            ("next_action", string(summary.recommended_action())),
        ]),
    ))
}

fn platform_access_review_records(
    runtime: &mut SmartHomeRuntime,
    principal_id: AgentId,
    now_ms: u64,
    query: &PlatformAccessReviewQuery,
) -> Result<(Vec<PlatformAccessReviewRecord>, PlatformAccessReviewSummary), ToolCallError> {
    let mut records = Vec::new();
    if platform_access_review_query_includes(query, PlatformAccessReviewKind::CommandRisk) {
        let command_query = default_platform_access_review_command_query(query);
        let (rows, _) =
            command_risk_audit_rows(runtime, principal_id.clone(), now_ms, &command_query)?;
        records.extend(
            rows.into_iter()
                .map(PlatformAccessReviewRecord::CommandRisk),
        );
    }
    if platform_access_review_query_includes(query, PlatformAccessReviewKind::AuthorizationGap) {
        let authorization_query = default_platform_access_review_authorization_query(query);
        let (rows, _) =
            authorization_gap_audit_rows(runtime, principal_id, now_ms, &authorization_query)?;
        records.extend(
            rows.into_iter()
                .map(PlatformAccessReviewRecord::AuthorizationGap),
        );
    }

    records.retain(|record| platform_access_review_record_matches(record, query));
    records.sort_by(|left, right| {
        platform_access_review_record_rank(right)
            .cmp(&platform_access_review_record_rank(left))
            .then_with(|| {
                platform_access_review_record_time(right)
                    .cmp(&platform_access_review_record_time(left))
            })
            .then_with(|| left.review_id().cmp(&right.review_id()))
    });
    let summary = PlatformAccessReviewSummary::from_records(&records);
    Ok((records, summary))
}

fn platform_access_review_query_includes(
    query: &PlatformAccessReviewQuery,
    kind: PlatformAccessReviewKind,
) -> bool {
    query.access_kinds.is_empty() || query.access_kinds.contains(&kind)
}

fn platform_access_review_record_matches(
    record: &PlatformAccessReviewRecord,
    query: &PlatformAccessReviewQuery,
) -> bool {
    if !platform_access_review_query_includes(query, record.review_kind()) {
        return false;
    }
    if query.requires_attention_only && !record.requires_attention() {
        return false;
    }
    if query.blocked_only && !record.blocked() {
        return false;
    }
    if query.denials_only && !record.is_denial() {
        return false;
    }
    if query.grant_review_only && !record.is_grant_review() {
        return false;
    }
    if query
        .bridge_id
        .as_ref()
        .is_some_and(|bridge_id| record.bridge_id() != Some(bridge_id))
    {
        return false;
    }
    if query
        .entity_id
        .as_ref()
        .is_some_and(|entity_id| record.entity_id() != Some(entity_id))
    {
        return false;
    }
    if query
        .capability_id
        .as_ref()
        .is_some_and(|capability_id| !record.has_capability(capability_id))
    {
        return false;
    }
    if query
        .risk_lane
        .as_ref()
        .is_some_and(|risk_lane| record.risk_lane() != risk_lane.as_str())
    {
        return false;
    }
    if query
        .risk_action
        .as_ref()
        .is_some_and(|risk_action| record.risk_action() != risk_action.as_str())
    {
        return false;
    }
    true
}

fn platform_access_review_record_rank(record: &PlatformAccessReviewRecord) -> u8 {
    if record.is_denial() || record.missing_capability_count() > 0 {
        6
    } else if record.is_failure_result() {
        5
    } else if record.is_grant_review() {
        4
    } else if record.is_approval_gated() {
        3
    } else if record.blocked() {
        2
    } else if record.requires_attention() {
        1
    } else {
        0
    }
}

fn platform_access_review_record_time(record: &PlatformAccessReviewRecord) -> u64 {
    match record {
        PlatformAccessReviewRecord::CommandRisk(row) => command_risk_sort_key(row),
        PlatformAccessReviewRecord::AuthorizationGap(row) => authorization_gap_row_time(row),
    }
}

fn platform_access_review_kind_label(kind: PlatformAccessReviewKind) -> &'static str {
    match kind {
        PlatformAccessReviewKind::CommandRisk => "command_risk",
        PlatformAccessReviewKind::AuthorizationGap => "authorization_gap",
    }
}

