fn runtime_maintenance_work_order_evidence_review_disposition_status(
    review: &RuntimeMaintenanceWorkOrderEvidenceReview,
) -> &'static str {
    if review.blocks_release() {
        "blocked"
    } else if review.operator_handoff() {
        "operator_handoff"
    } else {
        "accepted"
    }
}

